const item = $input.first().json;
return [{
  json: {
    jobTitle: item.title || item.jobTitle || 'Untitled',
    jobUrl: item.url || item.link || '',
    jobDescription: item.description || item.content || '',
    budget: item.budget || 'Not specified',
    clientRating: item.clientRating || null,
    clientSpent: item.clientSpent || 0,
    skillsRequired: item.skills || ''
  }
}];
